#!/usr/bin/env bash
# E4 attempt-local watchdog. It never discovers or kills by executable name:
# only PGIDs recorded by the attempt owner may be terminated.
set -euo pipefail
usage() { echo "Usage: $0 --output CSV --trigger FILE --host-role ROLE [--pid-file FILE] [--health-command COMMAND] [--startup-grace-seconds N] [--interval SECONDS] [--consecutive N] [--once]" >&2; }
output=""; trigger=""; role=""; pid_file=""; health_command=""; startup_grace="${E4_WATCHDOG_STARTUP_GRACE_SECONDS:-30}"; interval="${E4_WATCHDOG_INTERVAL_SECONDS:-1}"; consecutive="${E4_WATCHDOG_CONSECUTIVE_SAMPLES:-3}"; once=false
while (( $# )); do case "$1" in --output|--trigger|--host-role|--pid-file|--health-command|--startup-grace-seconds|--interval|--consecutive) key="${1#--}"; shift; (( $# )) || { usage; exit 2; }; case "$key" in output) output="$1";; trigger) trigger="$1";; host-role) role="$1";; pid-file) pid_file="$1";; health-command) health_command="$1";; startup-grace-seconds) startup_grace="$1";; interval) interval="$1";; consecutive) consecutive="$1";; esac; shift;; --once) once=true; shift;; *) usage; exit 2;; esac; done
[[ -n "$output" && -n "$trigger" && -n "$role" ]] || { usage; exit 2; }
[[ "$interval" =~ ^[1-9][0-9]*$ && "$consecutive" =~ ^[1-9][0-9]*$ && "$startup_grace" =~ ^[0-9]+$ ]] || { echo "watchdog interval/consecutive/startup-grace values are invalid" >&2; exit 2; }
mkdir -p "$(dirname "$output")" "$(dirname "$trigger")"; [[ -f "$output" ]] || echo 'timestamp_utc,elapsed_seconds,host_role,metric,value,threshold,state' > "$output"
started="$(date +%s)"; load_run=0; memory_run=0; swap_run=0; health_run=0; process_run=0
emit() { printf '%s,%s,%s,%s,%s,%s,%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$(( $(date +%s) - started ))" "$role" "$1" "${2:---}" "${3:---}" "$4" >> "$output"; }
stop() { local classification="${4:-SAFETY_STOP}"; [[ -e "$trigger" ]] || { tmp="$trigger.$$"; printf 'classification=%s\nhost_role=%s\nmetric=%s\nvalue=%s\nthreshold=%s\ntimestamp_utc=%s\n' "$classification" "$role" "$1" "$2" "$3" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$tmp"; mv "$tmp" "$trigger"; }; }
sample() {
  local available total mem_pct swap_total swap_free swap_pct load cpu_count load_per_cpu pid pgid cpu rss fd limit cpu_threshold="${E4_PROCESS_CPU_PERCENT:-95}" load_threshold="${E4_MAX_LOAD_PER_CPU:-2}" mem_threshold="${E4_MIN_AVAILABLE_MEMORY_PERCENT:-20}" swap_threshold="${E4_MAX_SWAP_USED_PERCENT:-10}" fd_pct="${E4_FD_PERCENT:-75}"
  available="$(awk '/^MemAvailable:/ {print $2}' /proc/meminfo 2>/dev/null || true)"; total="$(awk '/^MemTotal:/ {print $2}' /proc/meminfo 2>/dev/null || true)"
  if [[ "$available" =~ ^[0-9]+$ && "$total" =~ ^[1-9][0-9]*$ ]]; then mem_pct=$((available * 100 / total)); (( mem_pct < mem_threshold )) && memory_run=$((memory_run+1)) || memory_run=0; emit mem_available_percent "$mem_pct" "$mem_threshold" "$([[ $memory_run -ge $consecutive ]] && echo violating || echo ok)"; [[ $memory_run -ge $consecutive ]] && stop mem_available_percent "$mem_pct" "$mem_threshold"; else emit mem_available_percent -- "$mem_threshold" metric_unavailable; fi
  swap_total="$(awk '/^SwapTotal:/ {print $2}' /proc/meminfo 2>/dev/null || true)"; swap_free="$(awk '/^SwapFree:/ {print $2}' /proc/meminfo 2>/dev/null || true)"; if [[ "$swap_total" =~ ^[1-9][0-9]*$ && "$swap_free" =~ ^[0-9]+$ ]]; then swap_pct=$(( (swap_total - swap_free) * 100 / swap_total )); (( swap_pct > swap_threshold )) && swap_run=$((swap_run+1)) || swap_run=0; emit swap_used_percent "$swap_pct" "$swap_threshold" "$([[ $swap_run -ge $consecutive ]] && echo violating || echo ok)"; [[ $swap_run -ge $consecutive ]] && stop swap_used_percent "$swap_pct" "$swap_threshold"; else emit swap_used_percent -- "$swap_threshold" metric_unavailable; fi
  load="$(awk '{print $1}' /proc/loadavg 2>/dev/null || true)"; cpu_count="$(getconf _NPROCESSORS_ONLN 2>/dev/null || nproc 2>/dev/null || awk '/^processor[[:space:]]*:/ {count++} END {print count}' /proc/cpuinfo 2>/dev/null || true)"; if [[ "$load" =~ ^[0-9]+([.][0-9]+)?$ && "$cpu_count" =~ ^[1-9][0-9]*$ ]]; then load_per_cpu="$(awk -v load="$load" -v cpus="$cpu_count" 'BEGIN { printf "%.6f", load / cpus }')"; if awk -v value="$load_per_cpu" -v threshold="$load_threshold" 'BEGIN { exit !(value >= threshold) }'; then load_run=$((load_run+1)); else load_run=0; fi; emit load_1m "$load" "$cpu_count" observed; emit load_per_cpu "$load_per_cpu" "$load_threshold" "$([[ $load_run -ge $consecutive ]] && echo violating || echo ok)"; [[ $load_run -ge $consecutive ]] && stop load_per_cpu "$load_per_cpu" "$load_threshold"; else emit load_1m -- -- metric_unavailable; emit load_per_cpu -- "$load_threshold" metric_unavailable; fi
  if [[ -n "$pid_file" ]]; then pid="$(tr -d '[:space:]' < "$pid_file" 2>/dev/null || true)"; if (( $(date +%s) - started < startup_grace )); then emit process_alive -- 1 startup_grace; elif [[ ! "$pid" =~ ^[1-9][0-9]*$ ]] || ! kill -0 "$pid" 2>/dev/null; then process_run=$((process_run+1)); emit process_alive 0 1 "$([[ $process_run -ge $consecutive ]] && echo violating || echo ok)"; [[ $process_run -ge $consecutive ]] && stop process_alive 0 1 PROCESS_FAILURE; else process_run=0; emit process_alive 1 1 ok; fi
  pgid="$(ps -o pgid= -p "$pid" 2>/dev/null | tr -d '[:space:]' || true)"; emit pgid "${pgid:---}" -- ok
  cpu="$(ps -p "$pid" -o %cpu= 2>/dev/null | awk '{printf "%d",$1}' || true)"; if [[ "$cpu" =~ ^[0-9]+$ ]]; then emit process_cpu_percent "$cpu" "$cpu_threshold" "$([[ $cpu -ge $cpu_threshold ]] && echo observed || echo ok)"; else emit process_cpu_percent -- "$cpu_threshold" metric_unavailable; fi
  rss="$(ps -p "$pid" -o rss= 2>/dev/null | tr -d '[:space:]' || true)"; [[ "$rss" =~ ^[0-9]+$ ]] && emit process_rss_kib "$rss" -- ok || emit process_rss_kib -- -- metric_unavailable
  fd="$(find "/proc/$pid/fd" -maxdepth 1 -type l 2>/dev/null | wc -l | tr -d ' ')"; limit="$(awk '/Max open files/ {print $5}' "/proc/$pid/limits" 2>/dev/null || true)"; if [[ "$fd" =~ ^[0-9]+$ && "$limit" =~ ^[1-9][0-9]*$ ]]; then threshold=$((limit * fd_pct / 100)); emit process_fd_count "$fd" "$threshold" "$([[ $fd -ge $threshold ]] && echo violating || echo ok)"; [[ $fd -ge $threshold ]] && stop process_fd_count "$fd" "$threshold"; else emit process_fd_count -- -- metric_unavailable; fi; fi
  if [[ -n "$health_command" ]]; then if (( $(date +%s) - started < startup_grace )); then emit health -- 1 startup_grace; elif bash -c "$health_command" >/dev/null 2>&1; then health_run=0; emit health 1 1 ok; else health_run=$((health_run+1)); emit health 0 1 "$([[ $health_run -ge $consecutive ]] && echo violating || echo ok)"; [[ $health_run -ge $consecutive ]] && stop health 0 1 PROCESS_FAILURE; fi; fi
}
while :; do sample; [[ "$once" == true || -e "$trigger" ]] && break; sleep "$interval"; done
